does the job.

C strikes the perfect balance - enough abstraction to interact with the operating system without drowning in complexity, but transparent enough that you always understand what your code is actually doing. You can write an HTTP server in a weekend without needing an electrical engineering degree.

As for C++: Any C code that passes -Wpedantic compiles as C++.  Using classes, std::string, and vectors when you don't absolutely need them isn't sophistication - it's adding weight without benefit.

C++ can be great if you treat it like "C with some extras." The problem is people who treat it like a completely different language and pay the performance tax - both at runtime and compiletime.

1:16:45 simply serialization    "programs"_json >> Programs; or "programs"_json << Programs;
#pragma once
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <pfr/core_name.hpp>

// #include <boost/pfr/core_name.hpp>
// namespace pfr = boost::pfr;

template <typename T> concept Value = //
    std::is_floating_point_v<T>
    || std::is_integral_v<T>
    || std::is_same_v<T, QString>
    || std::is_same_v<T, QByteArray>;

template <typename T> concept Array = //
    requires(T r) { std::begin(r);std::end(r); } && !Value<T>;

template <typename T> concept Object = //
    std::is_aggregate_v<T>
    && std::is_class_v<T>
    && !Array<T>;

namespace Json {
class Serializer {
    QString fileName;
    QString name;

public:
    Serializer(const QString& fileName_)
        : fileName{fileName_} {
        if(!fileName.endsWith(u".json"_s)) fileName += u".json"_s;
    }

    void operator>>(auto& val) try {
        if(auto jVal = load(); jVal) rd(*jVal, val);
    } catch(std::invalid_argument& e) {
        qCritical() << e.what();
    }

    void operator<<(const auto& val) try {
        save(wr(val));
    } catch(std::invalid_argument& e) {
        qCritical() << e.what();
    }

private:
    bool save(QJsonValue jVal) {
        if(QFile file{fileName};
            !(jVal.isNull() || jVal.isUndefined()) && file.open(QFile::WriteOnly)) {
            auto doc = QJsonDocument::fromJson(file.readAll());
            file.write((jVal.isArray()
                    ? QJsonDocument{jVal.toArray()}
                    : QJsonDocument{jVal.toObject()})
                    .toJson());
            return true;
        } else qWarning() << file.fileName() << file.errorString();
        return false;
    }
    std::optional<QJsonValue> load() {
        if(QFile file{fileName}; file.open(QFile::ReadOnly)) {
            auto doc = QJsonDocument::fromJson(file.readAll());
            return doc.isArray() ? QJsonValue{doc.array()}
                                 : QJsonValue{doc.object()};
        } else qWarning() << file.fileName() << file.errorString();
        return std::nullopt;
    }

    QJsonValue wr(auto* val) { return val ? wr(*val) : QJsonValue::Null; }

    QJsonValue wr(const Value auto& val) { return {val}; }

    QJsonValue wr(const Array auto& val) {
        QJsonArray arr;
        for(auto&& var: val) arr.append(wr(var));
        return arr;
    }

    QJsonValue wr(const Object auto& val) {
        QJsonObject obj;
        auto wrf = [&obj, this]<class TF>(std::string_view name, const TF& field) {
            obj[QString::fromUtf8(name)] = wr(field);
        };
        pfr::for_each_field_with_name(val, wrf);
        return obj;
    }

    void rd(QJsonValue jval, auto* val) { qWarning(__PRETTY_FUNCTION__); }

    template <Value T>
    void rd(QJsonValue jval, T& val) {
        if(!(jval.isString() || jval.isDouble() || jval.isBool())) throw std::invalid_argument{__PRETTY_FUNCTION__};
        val = jval.toVariant().value<T>();
    }

    void rd(QJsonValue jval, Array auto& val) {
        if(!jval.isArray()) throw std::invalid_argument{__PRETTY_FUNCTION__};
        QJsonArray jArr = jval.toArray();
        if constexpr(requires { val.resize(0uz); }) val.resize(jArr.size());
        for(auto&& [src, dst]: std::ranges::zip_view(jArr, val)) rd(src, dst);
    }

    void rd(QJsonValue jval, Object auto& val) {
        if(!jval.isObject()) throw std::invalid_argument{__PRETTY_FUNCTION__};
        auto rdf = [this, &jval]<class TF>(std::string_view name, TF& field) {
            rd(jval[QString::fromUtf8(name)], field);
        };
        pfr::for_each_field_with_name(val, rdf);
    }
};
} // namespace Json

inline auto operator""_json(const char* str, size_t size) {
    return Json::Serializer{QString::fromUtf8(str, size)};
}

