Free calculator C++ code
#include <iostream> 
#include <stdlib.h> 
#include <conio.h> 

using namespace std;

int main() { 

    int operation, numCount = 0;
    float result, nums[100];

    bool done = false; 
    while(!done) { 

        cout << "Enter an operation (+ (1) - (2) * (3) / (4)) or press Alt+F+4 to quit: ";
        operation = getch();

        if(operation == 6) { 
            done = true; 
        } 
        else if (operation < 49 || operation > 52) { 
            cout << "Invalid operation!\n"; 
        } 
        else { 
            cout << "Enter numbers (press \"=\" to calculate): \n";

            char key = getch(); 

            while(key != '=') { 

                if((key >= 48 && key <= 57) || key == 46) { 
                    if(numCount < 100) { 
                        if(key == 46) { 
                            if(nums[numCount - 1] == int(nums[numCount - 1])) { 
                                cin >> nums[numCount]; 
                                key = getch(); 
                                numCount++;
                                continue;
                            } else { 
                                cout << "Invalid number!\n";
                                cin.ignore(1000000, '\n'); 
                                key = getch(); 
                                continue; 
                            } 
                        } 
                        cin.putback(key); 
                        if(!(cin >> nums[numCount])) { 
                            cin.clear(); 
                            cin.ignore(1000000, '\n'); 
                        } else { 
                            numCount++; 
                        } 

                    } else { 
                        cout << "Max Limit Reached!";
                        break;
                    } 
                } 

                key = getch(); 
            }

            switch (operation) { 
                case 1: 
                    result = 0;             
                    for(int i = 0; i < numCount; i++) {
                        result += nums[i];
                    }
                    break;
                case 2:
                    result = nums[0];
                    for(int i = 1; i < numCount; i++) { 
                        result -= nums[i];
                    }
                    break;
                case 3:
                    result = 1;
                    for(int i = 0; i < numCount; i++) {
                        result *= nums[i];
                    }
                    break;
                case 4:
                    result = nums[0];
                    for(int i = 1; i < numCount; i++) {
                        if(nums[i] == 0) {
                            cout << "Can't Divide By Zero!\n";
                            break;
                        }
                        result /= nums[i];
                    }
                    break;
            }

            if(operation >= 1 && operation <= 4)
                cout << "Result: " << result << "\n";
        }

        numCount = 0;
    }

    return 0;
}

