    const float phi_spacing = 0.02;

    while (true) {
        float z[width * height] = {0};
        char b[width * height];
        std::fill_n(b, width * height, ' ');

        for (float theta = 0; theta < 2 * M_PI; theta += theta_spacing) {
            for (float phi = 0; phi < 2 * M_PI; phi += phi_spacing) {
                float cosA = cos(A), sinA = sin(A);
                float cosB = cos(B), sinB = sin(B);
                float cosTheta = cos(theta), sinTheta = sin(theta);
                float cosPhi = cos(phi), sinPhi = sin(phi);

                float circlex = 2 + cosTheta;
                float circley = sinTheta;

                float x = circlex * (cosB * cosPhi + sinA * sinB * sinPhi) - circley * cosA * sinB;
                float y = circlex * (sinB * cosPhi - sinA * cosB * sinPhi) + circley * cosA * cosB;
                float z_val = 5 + cosA * circlex * sinPhi + circley * sinA;
                float ooz = 1 / z_val;

                int xp = (int)(width / 2 + 30 * ooz * x);
                int yp = (int)(height / 2 - 15 * ooz * y);

                int idx = xp + yp * width;
                float luminance = cosPhi * cosTheta * sinB - cosA * cosTheta * sinPhi - sinA * sinTheta + cosB * (cosA * sinTheta - cosTheta * sinA * sinPhi);

                if (idx >= 0 && idx < width * height && luminance > 0) {
                    if (ooz > z[idx]) {
                        z[idx] = ooz;
                        int luminance_index = (int)(luminance * 8);
                        const char luminance_chars[] = ".,-~:;=!*#$@";
