            for (i = 0; i < 6.28; i += 0.02) {
                float sini = sin(i), cosi = cos(i);
                float cosj = cos(j), sinj = sin(j);
                float sinA = sin(A), cosA = cos(A);
                float sinB = sin(B), cosB = cos(B);
                float h = cosj + 2;
                float D = 1 / (sini * h * sinA + sinj * cosA + 5);
                float t = sini * h * cosA - sinj * sinA;

                int x = (int)(40 + 30 * D * (cosi * h * cosB - t * sinB));
                int y = (int)(12 + 15 * D * (cosi * h * sinB + t * cosB));
                int o = x + 80 * y;
                int N = (int)(8 * ((sinj * sinA - sini * cosj * cosA) * cosB - sini * cosj * sinA - sinj * cosA - cosi * cosj * sinB));

                if (22 > y && y > 0 && x > 0 && 80 > x && D > z[o]) {
